    public string Vegetables { get; set; }
    public string Sauces { get; set; }
}

//Clase Director que utiliza la interfaz ISandwichBuilder para construir el objeto
public class SandwichMaker
{
    private ISandwichBuilder _builder;

    public SandwichMaker(ISandwichBuilder builder)
    {
        _builder = builder;
    }

    public void BuildSandwich()
    {
        _builder.AddBread();
        _builder.AddMeat();
        _builder.AddCheese();
        _builder.AddVegetables();
        _builder.AddSauces();
    }

