    public BLTSandwichBuilder()
    {
        _sandwich = new Sandwich();
    }

    public void AddBread()
    {
        _sandwich.Bread = "White";
    }

    public void AddMeat()
    {
        _sandwich.Meat = "Bacon";
    }

    public void AddCheese()
    {
        _sandwich.Cheese = "None";
    }

    public void AddVegetables()
    {
        _sandwich.Vegetables = "Lettuce, Tomato";
    }

    public void AddSauces()
    {
        _sandwich.Sauces = "Mayonnaise";
    }

    public Sandwich GetSandwich()
    {
        return _sandwich;
    }
}

//Clase concreta que implementa la interfaz ISandwichBuilder y que construye un sandwich tipo Club
public class ClubSandwichBuilder : ISandwichBuilder
{
    private Sandwich _sandwich;

    public ClubSandwichBuilder()
    {
        _sandwich = new Sandwich();
    }

    public void AddBread()
    {
        _sandwich.Bread = "Whole Wheat";
    }

    public void AddMeat()
    {
        _sandwich.Meat = "Turkey, Ham";
    }

    public void AddCheese()
    {
        _sandwich.Cheese = "American";
    }

    public void AddVegetables()
    {
        _sandwich.Vegetables = "Lettuce, Tomato, Onion, Pick";
    }

public void AddSauces()
{
    _sandwich.Sauces = "Mayonnaise, Mustard";
}

public Sandwich GetSandwich()
{
    return _sandwich;
}
}

//Clase Sandwich que representa el objeto a construir
public class Sandwich
{
    public string Bread { get; set; }
    public string Meat { get; set; }
    public string Cheese { get; set; }
    public string Vegetables { get; set; }
    public string Sauces { get; set; }
}

//Clase Director que utiliza la interfaz ISandwichBuilder para construir el objeto
public class SandwichMaker
{
    private ISandwichBuilder _builder;

    public SandwichMaker(ISandwichBuilder builder)
    {
        _builder = builder;
    }

    public void BuildSandwich()
    {
        _builder.AddBread();
        _builder.AddMeat();
        _builder.AddCheese();
        _builder.AddVegetables();
        _builder.AddSauces();
    }

