        bltMaker.BuildSandwich();
        Sandwich blt = bltMaker.GetSandwich();

        //Creación de un sandwich Club
        ISandwichBuilder clubBuilder = new ClubSandwichBuilder();
        SandwichMaker clubMaker = new SandwichMaker(clubBuilder);
        clubMaker.BuildSandwich();
        Sandwich club = clubMaker.GetSandwich();

        Console.WriteLine("BLT Sandwich: Bread - " + blt.Bread + ", Meat - " + blt.Meat + ", Cheese - " + blt.Cheese + ", Vegetables - " + blt.Vegetables + ", Sauces - " + blt.Sauces);
        Console.WriteLine("Club Sandwich: Bread - " + club.Bread + ", Meat - " + club.Meat + ", Cheese - " + club.Cheese + ", Vegetables - " + club.Vegetables + ", Sauces - " + club.Sauces);

